namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on civilization." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, Code = "CS101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen has 15 years of experience teaching introductory CS courses. Her research focuses on CS education and making programming accessible to all students.", Email = "s.chen@university.edu" }
            },
            new()
            {
                Id = 2, Code = "CS301", Title = "Data Structures and Algorithms",
                Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, hash tables, sorting, and complexity analysis.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true,
                Instructor = new() { Id = 2, Name = "Prof. James Martinez", Title = "Professor", Bio = "Prof. Martinez is a leading researcher in algorithm optimization with publications in top-tier journals. He brings real-world industry experience from his work at major tech companies.", Email = "j.martinez@university.edu" }
            },
            new()
            {
                Id = 3, Code = "CS420", Title = "Machine Learning",
                Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation techniques.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false,
                Instructor = new() { Id = 3, Name = "Dr. Aisha Patel", Title = "Assistant Professor", Bio = "Dr. Patel joined the department after completing postdoctoral research at MIT. She specializes in deep learning and natural language processing.", Email = "a.patel@university.edu" }
            },
            new()
            {
                Id = 4, Code = "MATH201", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, and eigenvalues. Essential for advanced mathematics and computer science.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true,
                Instructor = new() { Id = 4, Name = "Dr. Robert Kim", Title = "Professor", Bio = "Dr. Kim is an award-winning educator with over 20 years in the mathematics department. His textbook on linear algebra is used at universities worldwide.", Email = "r.kim@university.edu" }
            },
            new()
            {
                Id = 5, Code = "MATH301", Title = "Differential Equations",
                Description = "Methods for solving ordinary differential equations with applications in physics and engineering. Covers first-order, second-order, and systems of equations.",
                Credits = 4, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false,
                Instructor = new() { Id = 5, Name = "Dr. Elena Volkov", Title = "Associate Professor", Bio = "Dr. Volkov specializes in applied mathematics and mathematical modeling. She has collaborated with NASA on orbital mechanics research.", Email = "e.volkov@university.edu" }
            },
            new()
            {
                Id = 6, Code = "PHYS101", Title = "General Physics I",
                Description = "Introduction to classical mechanics, thermodynamics, and waves. Includes laboratory sessions demonstrating fundamental physical principles.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true,
                Instructor = new() { Id = 6, Name = "Dr. Michael Torres", Title = "Professor", Bio = "Dr. Torres is a passionate educator known for his engaging demonstrations. His research in condensed matter physics has been published in Nature and Physical Review Letters.", Email = "m.torres@university.edu" }
            },
            new()
            {
                Id = 7, Code = "PHYS310", Title = "Quantum Mechanics",
                Description = "Introduction to quantum theory including wave functions, Schrödinger equation, quantum states, and measurement. Prerequisites: PHYS101, MATH301.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false,
                Instructor = new() { Id = 7, Name = "Dr. Lisa Wang", Title = "Associate Professor", Bio = "Dr. Wang conducts research in quantum computing and quantum information theory. She previously worked at CERN on particle physics experiments.", Email = "l.wang@university.edu" }
            },
            new()
            {
                Id = 8, Code = "ENG110", Title = "Academic Writing",
                Description = "Develop skills in critical reading, argumentation, and academic essay writing. Emphasis on clear prose, proper citation, and revision strategies.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Id = 8, Name = "Prof. David Okafor", Title = "Senior Lecturer", Bio = "Prof. Okafor is a published author and writing coach with expertise in rhetoric and composition. He has mentored hundreds of students in academic writing.", Email = "d.okafor@university.edu" }
            },
            new()
            {
                Id = 9, Code = "ENG250", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present. Examines major authors, movements, and cultural contexts.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentId = 4, DepartmentName = "English", IsFeatured = false,
                Instructor = new() { Id = 9, Name = "Dr. Maria Santos", Title = "Associate Professor", Bio = "Dr. Santos specializes in 20th-century American fiction and multicultural literature. She is the author of two critically acclaimed literary studies.", Email = "m.santos@university.edu" }
            },
            new()
            {
                Id = 10, Code = "HIST101", Title = "World Civilizations",
                Description = "A broad survey of world history from ancient civilizations through the modern era. Explores political, cultural, and economic developments across continents.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 5, DepartmentName = "History", IsFeatured = true,
                Instructor = new() { Id = 10, Name = "Dr. Thomas Brennan", Title = "Professor", Bio = "Dr. Brennan is a historian specializing in comparative civilizations. He has authored five books and received multiple teaching excellence awards.", Email = "t.brennan@university.edu" }
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

